// Core tests: the 14 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every expected value below was computed by hand from the SPEC's
// rules; the hand derivations are listed in AUTHOR-CHECK.md and in the
// comments here.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatDecimal,
  formatInteger,
  run,
} from "../public/js/core/lighting-lumen.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  mode: "dimensions",
  lengthM: "4.0",
  widthM: "3.5",
  areaUnit: "m2",
  areaValue: "20.00",
  roomType: "living",
  bulbLumens: "800",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("worked anchors: every room type maps to its pinned target lux", () => {
  // Area 10.00 m^2, one 1000 lm bulb: total = 10 x lux, count and
  // achieved follow directly.
  const expected = {
    living: { targetLux: 100, totalLumens: 1000, bulbCount: 1, installedLumens: 1000, achievedLux: 100 },
    bedroom: { targetLux: 75, totalLumens: 750, bulbCount: 1, installedLumens: 1000, achievedLux: 100 },
    kitchen: { targetLux: 100, totalLumens: 1000, bulbCount: 1, installedLumens: 1000, achievedLux: 100 },
    bathroom: { targetLux: 100, totalLumens: 1000, bulbCount: 1, installedLumens: 1000, achievedLux: 100 },
    study: { targetLux: 300, totalLumens: 3000, bulbCount: 3, installedLumens: 3000, achievedLux: 300 },
    corridor: { targetLux: 100, totalLumens: 1000, bulbCount: 1, installedLumens: 1000, achievedLux: 100 },
  };
  for (const [roomType, want] of Object.entries(expected)) {
    const outcome = run({
      mode: "area",
      lengthM: "4.0",
      widthM: "3.5",
      areaUnit: "m2",
      areaValue: "10.00",
      roomType,
      bulbLumens: "1000",
    });
    assert.equal(outcome.ok, true);
    assert.equal(outcome.result.areaM2, 10);
    assert.deepEqual(
      {
        targetLux: outcome.result.targetLux,
        totalLumens: outcome.result.totalLumens,
        bulbCount: outcome.result.bulbCount,
        installedLumens: outcome.result.installedLumens,
        achievedLux: outcome.result.achievedLux,
      },
      want,
    );
  }
});

test("boundary: length/width 0.5 and 100.0 succeed, 0.4 and 100.1 are RANGE", () => {
  // 100.0 x 100.0 living room: area 10000, total 1,000,000, 1250 bulbs
  // of 800 lm, installed 1,000,000, achieved 100.
  const max = run({ ...base, lengthM: "100.0", widthM: "100.0" });
  assert.equal(max.ok, true);
  assert.deepEqual(max.result, {
    areaM2: 10000,
    targetLux: 100,
    totalLumens: 1000000,
    bulbCount: 1250,
    installedLumens: 1000000,
    achievedLux: 100,
  });
  assert.deepEqual(errorOf({ ...base, lengthM: "0.4" }), {
    code: "RANGE",
    field: "lengthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, widthM: "100.1" }), {
    code: "RANGE",
    field: "widthM",
    row: null,
  });
});

test("boundary: area m2 0.25 and 10000 succeed, 0.24 and 10000.01 are RANGE", () => {
  // 0.25 m^2 living: total 25, 1 bulb of 800, achieved 3200.
  const min = run({ ...base, mode: "area", areaValue: "0.25" });
  assert.equal(min.ok, true);
  assert.deepEqual(min.result, {
    areaM2: 0.25,
    targetLux: 100,
    totalLumens: 25,
    bulbCount: 1,
    installedLumens: 800,
    achievedLux: 3200,
  });
  assert.deepEqual(errorOf({ ...base, mode: "area", areaValue: "0.24" }), {
    code: "RANGE",
    field: "areaValue",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, mode: "area", areaValue: "10000.01" }), {
    code: "RANGE",
    field: "areaValue",
    row: null,
  });
});

test("boundary: ping 3000 study succeeds, 0.07 and 3000.01 are RANGE", () => {
  // 3000 ping study: area = 3000 x 400/121 = 1,200,000/121
  // = 9917.3553... -> 9917.36; total = 360,000,000/121
  // = 2,975,206.6115... -> 2,975,207; 30 bulbs of 100000;
  // installed 3,000,000; achieved = 3,000,000 x 121/1,200,000 = 302.5.
  const max = run({
    ...base,
    mode: "area",
    areaUnit: "ping",
    areaValue: "3000.00",
    roomType: "study",
    bulbLumens: "100000",
  });
  assert.equal(max.ok, true);
  assert.deepEqual(max.result, {
    areaM2: 9917.36,
    targetLux: 300,
    totalLumens: 2975207,
    bulbCount: 30,
    installedLumens: 3000000,
    achievedLux: 302.5,
  });
  assert.deepEqual(
    errorOf({ ...base, mode: "area", areaUnit: "ping", areaValue: "0.07" }),
    { code: "RANGE", field: "areaValue", row: null },
  );
  assert.deepEqual(
    errorOf({ ...base, mode: "area", areaUnit: "ping", areaValue: "3000.01" }),
    { code: "RANGE", field: "areaValue", row: null },
  );
});

test("boundary: bulb 1 and 100000 succeed, 100001 is RANGE", () => {
  // Living 14 m^2, 1 lm bulbs: total 1400, 1400 bulbs, achieved 100.
  const one = run({ ...base, bulbLumens: "1" });
  assert.equal(one.ok, true);
  assert.equal(one.result.bulbCount, 1400);
  assert.equal(one.result.installedLumens, 1400);
  assert.equal(one.result.achievedLux, 100);
  assert.deepEqual(errorOf({ ...base, bulbLumens: "100001" }), {
    code: "RANGE",
    field: "bulbLumens",
    row: null,
  });
});

test("one lumen over an exact multiple adds one bulb", () => {
  // 20.01 m^2 living: total 2001, 1000 lm bulbs -> 3 bulbs, installed
  // 3000, achieved 3000/20.01 = 149.925... -> 149.9.
  const outcome = run({
    ...base,
    mode: "area",
    areaValue: "20.01",
    bulbLumens: "1000",
  });
  assert.equal(outcome.ok, true);
  assert.deepEqual(outcome.result, {
    areaM2: 20.01,
    targetLux: 100,
    totalLumens: 2001,
    bulbCount: 3,
    installedLumens: 3000,
    achievedLux: 149.9,
  });
});

test("achievedLux half-up tie: 76.25 rounds to 76.3, not 76.2", () => {
  // 1.6 x 1.0 bedroom: area 1.6, total 120, one 122 lm bulb,
  // installed 122, achieved 122/1.6 = 76.25 exactly; half-up gives
  // 76.3 (banker's rounding would give 76.2).
  const outcome = run({
    ...base,
    lengthM: "1.6",
    widthM: "1.0",
    roomType: "bedroom",
    bulbLumens: "122",
  });
  assert.equal(outcome.ok, true);
  assert.deepEqual(outcome.result, {
    areaM2: 1.6,
    targetLux: 75,
    totalLumens: 120,
    bulbCount: 1,
    installedLumens: 122,
    achievedLux: 76.3,
  });
});

test("capacity: a 9-unit value is INPUT_LIMIT on every numeric field, including inactive ones", () => {
  assert.deepEqual(errorOf({ ...base, lengthM: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "lengthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, widthM: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "widthM",
    row: null,
  });
  // Inactive areaValue in dimensions mode: still capacity-checked.
  assert.deepEqual(errorOf({ ...base, areaValue: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "areaValue",
    row: null,
  });
  // Inactive lengthM/widthM in area mode: still capacity-checked.
  assert.deepEqual(errorOf({ ...base, mode: "area", lengthM: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "lengthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, mode: "area", widthM: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "widthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, bulbLumens: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "bulbLumens",
    row: null,
  });
});

test("an inactive field is capacity- and surrogate-checked but otherwise ignored", () => {
  // A lone surrogate in the inactive areaValue field is UNICODE.
  assert.deepEqual(errorOf({ ...base, areaValue: "\uD800" }), {
    code: "UNICODE",
    field: "areaValue",
    row: null,
  });
  // A lone surrogate in the inactive lengthM field (area mode) is UNICODE.
  assert.deepEqual(errorOf({ ...base, mode: "area", lengthM: "\uD800" }), {
    code: "UNICODE",
    field: "lengthM",
    row: null,
  });
  // Arbitrary grammar-breaking text in the inactive lengthM field is ignored.
  const ignored = run({ ...base, mode: "area", lengthM: "garbage!" });
  assert.equal(ignored.ok, true);
  assert.equal(ignored.result.totalLumens, 2000);
  // An invalid enum value in the inactive areaUnit field is ignored.
  const ignoredUnit = run({ ...base, areaUnit: "xx" });
  assert.equal(ignoredUnit.ok, true);
  assert.equal(ignoredUnit.result.totalLumens, 1400);
  // Arbitrary text in the inactive areaValue field (dimensions mode)
  // is ignored as long as it fits the capacity.
  const ignoredArea = run({ ...base, areaValue: "garbage!" });
  assert.equal(ignoredArea.ok, true);
  assert.equal(ignoredArea.result.totalLumens, 1400);
});

test("an active field reports UNICODE before EMPTY and grammar", () => {
  assert.deepEqual(errorOf({ ...base, lengthM: "\uD800" }), {
    code: "UNICODE",
    field: "lengthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, mode: "area", areaValue: "\uD800" }), {
    code: "UNICODE",
    field: "areaValue",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lengthM: "" }), {
    code: "EMPTY",
    field: "lengthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, mode: "area", areaValue: "" }), {
    code: "EMPTY",
    field: "areaValue",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, bulbLumens: "" }), {
    code: "EMPTY",
    field: "bulbLumens",
    row: null,
  });
});

test("length grammar: trailing dot, leading dot, leading zero, sign, blank and exponent are DECIMAL_FORMAT", () => {
  for (const bad of ["4.", ".5", "04.0", "+4", "4 ", " 4", "1e3", "４.0", "4.25"]) {
    assert.deepEqual(errorOf({ ...base, lengthM: bad }), {
      code: "DECIMAL_FORMAT",
      field: "lengthM",
      row: null,
    });
  }
});

test("area grammar: two decimals pass, three decimals are DECIMAL_FORMAT", () => {
  const two = run({ ...base, mode: "area", areaValue: "12.55", roomType: "bedroom" });
  assert.equal(two.ok, true);
  // 12.55 x 75 = 941.25 -> 941; two 800 lm bulbs; 1600/12.55 = 127.49... -> 127.5.
  assert.deepEqual(two.result, {
    areaM2: 12.55,
    targetLux: 75,
    totalLumens: 941,
    bulbCount: 2,
    installedLumens: 1600,
    achievedLux: 127.5,
  });
  assert.deepEqual(errorOf({ ...base, mode: "area", areaValue: "12.555" }), {
    code: "DECIMAL_FORMAT",
    field: "areaValue",
    row: null,
  });
});

test("bulb grammar: decimals, leading zeros and signs are INTEGER_FORMAT", () => {
  for (const bad of ["800.0", "08", "+800", "-800", "8.5", "800 "]) {
    assert.deepEqual(errorOf({ ...base, bulbLumens: bad }), {
      code: "INTEGER_FORMAT",
      field: "bulbLumens",
      row: null,
    });
  }
});

test("enum fields: empty or unlisted values are ENUM", () => {
  assert.deepEqual(errorOf({ ...base, mode: "" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, mode: "DIMENSIONS" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, mode: "area", areaUnit: "" }), {
    code: "ENUM",
    field: "areaUnit",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, mode: "area", areaUnit: "sqft" }), {
    code: "ENUM",
    field: "areaUnit",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, roomType: "" }), {
    code: "ENUM",
    field: "roomType",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...base, mode: "wrong", lengthM: "bad" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lengthM: "bad", widthM: "" }), {
    code: "DECIMAL_FORMAT",
    field: "lengthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, widthM: "", roomType: "garage" }), {
    code: "EMPTY",
    field: "widthM",
    row: null,
  });
  // In dimensions mode the inactive areaValue capacity error fires in
  // field order, before the later roomType enum error.
  assert.deepEqual(
    errorOf({ ...base, areaValue: "123456789", roomType: "garage" }),
    { code: "INPUT_LIMIT", field: "areaValue", row: null },
  );
  assert.deepEqual(errorOf({ ...base, roomType: "garage", bulbLumens: "0" }), {
    code: "ENUM",
    field: "roomType",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.widthM;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, lengthM: 4.0 }), schema);
  assert.deepEqual(errorOf({ ...base, bulbLumens: null }), schema);
  assert.deepEqual(errorOf(["dimensions"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("dimensions"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "lengthM", {
    enumerable: true,
    get() {
      return "4.0";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...base };
  stringObject.lengthM = new String("4.0");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("the core does not mutate its input", () => {
  const input = { ...base, roomType: "study" };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...base, lengthM: "100.1" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("property: total lumens never decrease as the area grows", () => {
  let previous = -Infinity;
  for (const areaValue of ["0.25", "1.00", "5.00", "12.50", "20.00", "100.00", "10000.00"]) {
    const outcome = run({ ...base, mode: "area", areaValue });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.totalLumens >= previous);
    previous = outcome.result.totalLumens;
  }
});

test("display formatting: grouped integers and decimals", () => {
  assert.equal(formatInteger(1400), "1,400");
  assert.equal(formatInteger(3000000), "3,000,000");
  assert.equal(formatInteger(100), "100");
  assert.equal(formatDecimal(114.3), "114.3");
  assert.equal(formatDecimal(19.83), "19.83");
  assert.equal(formatDecimal(10000), "10,000");
  assert.equal(formatDecimal(9917.36), "9,917.36");
  assert.equal(formatDecimal(0.26), "0.26");
});
